    let rest
    if (typeof crit === "number") rest = crit
    else if (typeof crit === "string") {
      const m = /^(<=|>=|<>|=|<|>)?([\s\S]*)$/.exec(crit)
      op = m[1] || "="
      rest = m[2]
      if (op === "<>") return null
      const n = textToNumber(rest)
      if (n != null) rest = n
      else if (op !== "=" || rest === "" || hasWild(rest) || /^(true|false)$/i.test(rest) || errFromCode(rest)) return null
    } else return null
    if (typeof rest === "string") {
      const e = idx.text.get(rest.toLowerCase())
      return e ? { sum: e.sum, count: e.count, nums: e.nums } : { sum: 0, count: 0, nums: 0 }
    }
