  def("ENCODEURL", "s", (s) => encodeURIComponent(s))

  /* ---------- date & time ---------- */
  const DATE_MAX = 2958465
  const serialOk = (n) => (n < 0 || n > DATE_MAX + 0.99999 ? ERR.NUM : n)
  def("TODAY", "", () => todaySerial(), { volatile: true })
  def("NOW", "", () => nowSerial(), { volatile: true })
  def("DATE", "i,i,i", (y, m, d) => {
    y = fixYear(y)
    if (y < 0 || y > 9999) return ERR.NUM
    return serialOk(serialFromYMD(y, m, d))
  })
  def("TIME", "i,i,i", (h, m, s) => {
    const t = (h * 3600 + m * 60 + s) / 86400
    if (t < 0) return ERR.NUM
    return t - Math.floor(t)
  })
  const partFn = (k) => (x) => (x < 0 ? ERR.NUM : dateParts(x)[k])
  def("YEAR", "n", partFn("y"))
  def("MONTH", "n", partFn("m"))
  def("DAY", "n", partFn("d"))
  def("HOUR", "n", partFn("H"))
  def("MINUTE", "n", partFn("M"))
  def("SECOND", "n", partFn("S"))
  def("DATEVALUE", "s", (s) => {
    const d = parseDateText(s)
    return d ? Math.floor(d.v) : ERR.VALUE
  })
  def("TIMEVALUE", "s", (s) => {
    const d = parseDateText(s)
    return d ? d.v - Math.floor(d.v) : ERR.VALUE
  })
  def("WEEKDAY", "n,i?", (x, type = 1) => {
    if (x < 0) return ERR.NUM
    const wd = dateParts(x).wd // 0 = Sunday
    if (type === 1 || type === 17) return wd + 1
    if (type === 2 || type === 11) return ((wd + 6) % 7) + 1
    if (type === 3) return (wd + 6) % 7
    if (type >= 12 && type <= 16) return ((wd - (type - 10) + 7) % 7) + 1
    return ERR.NUM
  })
  function isoWeek(x) {
    const p = dateParts(x)
    const d = new Date(Date.UTC(p.y, p.m - 1, p.d))
    const day = d.getUTCDay() || 7
    d.setUTCDate(d.getUTCDate() + 4 - day)
    const y0 = new Date(Date.UTC(d.getUTCFullYear(), 0, 1))
    return Math.ceil(((d - y0) / DAY_MS + 1) / 7)
  }
  def("ISOWEEKNUM", "n", (x) => (x < 0 ? ERR.NUM : isoWeek(x)))
  def("WEEKNUM", "n,i?", (x, type = 1) => {
    if (x < 0) return ERR.NUM
    if (type === 21) return isoWeek(x)
    const start = { 1: 0, 2: 1, 11: 1, 12: 2, 13: 3, 14: 4, 15: 5, 16: 6, 17: 0 }[type]
    if (start === undefined) return ERR.NUM
    const p = dateParts(x)
    const jan1 = serialFromYMD(p.y, 1, 1)
    const wd1 = dateParts(jan1).wd
    const offset = (wd1 - start + 7) % 7
    return Math.floor((Math.floor(x) - jan1 + offset) / 7) + 1
  })
  function addMonths(x, n) {
    const p = dateParts(x)
    const total = p.y * 12 + (p.m - 1) + n
    const y = Math.floor(total / 12)
    const m = (total % 12) + 1
    return { y, m, d: Math.min(p.d, daysInMonth(y, m)) }
  }
