  const META_KEYS = ["cf", "dv", "tables", "filter", "charts", "pivots", "slicers", "print", "breaks"]
  const metaGet = (sh, k) => (k === "merges" ? sh.merges.map((m) => [m.r1, m.c1, m.r2, m.c2]) : k === "freeze" ? [sh.freeze.r, sh.freeze.c] : sh[k])
