      const tr = r + dr
      const tc = c + dc
      if (tr < 0 || tc < 0 || tr >= MAXR || tc >= MAXC) continue
      writeCell(dst, tr, tc, ct ? { v: null, f: null, l: null, rt: null, s: null, ...ct } : null, res)
      const had = dst.comments.get(ck(tr, tc))
      if (comment || had) invComments.push({ t: "comment", s: dst.id, r: tr, c: tc, v: had ?? null })
