    if (g.r2 - g.r1 >= 201 || g.c2 - g.c1 >= 51) return toast(t("Select up to 201 rows and 51 columns to copy formatting.", "حدد حتى 201 صفًا و51 عمودًا لنسخ التنسيق."))
    const styles = []
    for (let r = g.r1; r <= Math.min(g.r2, g.r1 + 200); r++) {
      const row = []
      for (let c = g.c1; c <= Math.min(g.c2, g.c1 + 50); c++) row.push(styleOf(sh.styleIdAt(r, c)))
      styles.push(row)
    }
    const merges = sh.merges.filter((m) => m.r1 >= g.r1 && m.r2 <= g.r2 && m.c1 >= g.c1 && m.c2 <= g.c2).map((m) => [m.r1 - g.r1, m.c1 - g.c1, m.r2 - g.r1, m.c2 - g.c1])
