  function tableStyleItems() {
    const items = []
    for (const k of TABLE_KINDS) {
      items.push({ head: { light: t("Light", "فاتح"), medium: t("Medium", "متوسط"), dark: t("Dark", "داكن") }[k] })
      const row = h("div.ds-tstyles")
      for (let i = 1; i <= 6; i++) {
        const id = k + "-" + i
        const d = tableStyleDef(id)
        const b = h("button.ds-tstyle", { title: id, "aria-label": id })
        b.innerHTML = `<i style="background:${d.head.bg || "transparent"};border-bottom:2px solid ${d.head.bb ? d.head.bb.split(" ")[1] : d.head.bg}"></i><i style="background:${d.band}"></i><i style="background:${d.band2 || "transparent"}"></i><i style="background:${d.band}"></i>`
        b.addEventListener("click", () => {
          closePopups()
          runCmd("formatTable", id)
        })
        row.append(b)
      }
      items.push({ node: row })
    }
    return items
  }
  function cellStyleItems() {
    const grid = h("div.ds-cstyles")
    for (const cs of [...CELL_STYLES, ...wb.styles]) {
      const s = cs.s
      const b = h("button.ds-cstyle", { style: { background: s.bg || "", color: s.fc || "", fontWeight: s.b ? "700" : "", fontStyle: s.i ? "italic" : "", borderBottom: s.bb ? "2px solid " + s.bb.split(" ")[1] : "" } }, cs.name)
      b.addEventListener("click", () => {
        closePopups()
        runCmd("cellStyle", cs.id)
      })
      grid.append(b)
    }
    return [{ node: grid }, "-", { label: t("New cell style…", "نمط خلية جديد…"), icon: "plus", run: () => newCellStyle() }]
  }
  function themeItems() {
    return Object.entries(THEMES).map(([id, th]) => ({ label: th.name, html: `<i class="ds-themesw">${th.colors.map((c) => `<b style="background:${c}"></b>`).join("")}</i>${esc(th.name)}`, checked: (wb.props.theme || "durar") === id, run: () => runCmd("theme", id) }))
  }

