  /* groups are getters: updateContextTabs only needs the ids, and building a group makes DOM. */
  function contextTabs() {
    const out = []
    if (!wb || !sh) return out
    const tb = wb.tableAt(sh.id, sel.r, sel.c)
    if (tb) out.push({ id: "tabledesign", label: t("Table Design", "تصميم الجدول"), ctx: true, get groups() { return tableDesignGroups(tb) } })
    if (selectedObject?.kind === "chart") out.push({ id: "chartdesign", label: t("Chart", "المخطط"), ctx: true, get groups() { return chartDesignGroups() } })
    if (wb.tableMap && sh.pivots.some((p) => p.out && sel.r >= p.out[0] && sel.r <= p.out[2] && sel.c >= p.out[1] && sel.c <= p.out[3])) out.push({ id: "pivotdesign", label: t("PivotTable", "الجدول المحوري"), ctx: true, get groups() { return pivotDesignGroups() } })
    return out
  }

  /* ---------- ribbon rendering ---------- */
  let ribbonTab = readPref("ribbonTab", "home")
  function renderTabs() {
    const tabs = [{ id: "file", label: t("File", "ملف") }, ...RIBBON(), ...contextTabs()]
    if (!tabs.some((x) => x.id === ribbonTab)) ribbonTab = "home"
    ui.tabs.innerHTML = ""
    for (const tab of tabs) {
      const b = h("button.ds-tab" + (tab.ctx ? ".ctx" : "") + (tab.id === "file" ? ".file" : ""), { role: "tab", "aria-selected": String(tab.id === ribbonTab), type: "button" }, tab.label)
      b.addEventListener("click", () => {
        if (tab.id === "file") return openBackstage()
        ribbonTab = tab.id
        writePref("ribbonTab", ribbonTab)
        if (ui.root.classList.contains("ribbon-min")) ui.root.classList.add("ribbon-peek")
        renderTabs()
        renderRibbon()
      })
      ui.tabs.append(b)
    }
    const tell = h("div.ds-tellme", h("span", { html: icon("search") }), h("input", { placeholder: t("Search commands", "ابحث في الأوامر"), "aria-label": t("Search commands", "ابحث في الأوامر") }))
    const ti = tell.querySelector("input")
    ti.addEventListener("input", () => tellMe(ti))
    ti.addEventListener("keydown", (e) => {
      e.stopPropagation()
      if (e.key === "Escape") {
        ti.value = ""
        closePopups()
        focusGrid()
      }
      if (e.key === "ArrowDown") popup?.el.querySelector("button")?.focus()
      if (e.key === "Enter") popup?.el.querySelector("button")?.click()
    })
    ui.tabs.append(tell, h("button.ds-icon.ds-ribbontoggle", { title: t("Collapse the ribbon", "طي الشريط"), html: icon("up"), on: { click: () => runCmd("collapseRibbon") } }))
  }
  function tellMe(inp) {
    const q = inp.value.trim().toLowerCase()
    if (!q) return closePopups()
    const hits = Object.values(C)
      .filter((c) => c.label && c.label.toLowerCase().includes(q) && !["contextMenu", "tellMe"].includes(c.id))
      .slice(0, 12)
    const fns = FN_NAMES().filter((n) => n.toLowerCase().startsWith(q)).slice(0, 4)
    const items = hits.map((c) => ({ label: c.label, icon: c.icon, kbd: c.key ? keyLabel(c.key) : null, run: () => ((inp.value = ""), runCmd(c.id)) }))
    for (const f of fns) items.push({ label: t("Insert function ", "إدراج الدالة ") + f, icon: "fx", run: () => ((inp.value = ""), insertFunctionCall(f)) })
    if (!items.length) items.push({ label: t("No matching commands", "لا توجد أوامر مطابقة"), disabled: true })
    menu(items, inp)
    inp.focus()
  }
  const keyLabel = (k) => k.replace("Ctrl", MOD).replace("ArrowRight", "→").replace("ArrowLeft", "←")
  function btnFor(spec) {
    if (spec instanceof Node) return spec
    if (spec && spec.node) return spec.node
    // "bold" icon button · "+wrap" icon + label · { cmd, big, arg, icon, tip, label } · menu/split/select objects
    if (typeof spec === "string") {
      const labelled = spec[0] === "+"
      return cmdButton({ cmd: labelled ? spec.slice(1) : spec, label: labelled })
    }
    if (spec.type === "menu") {
      const b = h("button.ds-rb" + (spec.big ? ".big" : "") + ".menu", { type: "button", title: spec.tip || spec.label, "aria-haspopup": "menu" }, h("span", { html: icon(spec.icon) }), spec.label ? h("em", spec.label) : null, h("span.ds-caret", { html: icon("down") }))
      b.addEventListener("click", () => menu(typeof spec.items === "function" ? spec.items() : spec.items, b))
      return b
    }
    if (spec.type === "split") {
      const c = C[spec.cmd]
      const wrap = h("span.ds-split" + (spec.big ? ".big" : ""))
      const main = cmdButton({ cmd: spec.cmd, big: spec.big, label: spec.label })
      const more = h("button.ds-rb.more", { type: "button", title: c.label + " · " + t("options", "خيارات"), "aria-haspopup": "menu", html: icon("down") })
      more.addEventListener("click", () => menu(typeof spec.items === "function" ? spec.items() : spec.items, wrap))
      wrap.append(main, more)
      return wrap
    }
    if (spec.type === "color") {
      const c = C[spec.cmd]
      const wrap = h("span.ds-split.color")
      const main = cmdButton({ cmd: spec.cmd })
      main.dataset.color = spec.cmd
      const more = h("button.ds-rb.more", { type: "button", title: c.label, "aria-haspopup": "dialog", html: icon("down") })
      more.addEventListener("click", () => colorPicker(wrap, (col) => runCmd(spec.cmd, col), { none: spec.cmd === "fillColor", autoLabel: spec.cmd === "fillColor" ? t("No fill", "بلا تعبئة") : t("Automatic", "تلقائي") }))
      wrap.append(main, more)
      return wrap
    }
    if (spec.type === "font") {
      const inp = h("input.ds-rsel.font", { list: "ds-fonts", "aria-label": t("Font", "الخط"), spellcheck: "false" })
      inp.dataset.role = "font"
      const dl = h("datalist#ds-fonts", FONTS.map((f) => h("option", { value: f })))
      inp.addEventListener("change", () => runCmd("formatFont", inp.value))
      inp.addEventListener("keydown", (e) => {
        e.stopPropagation()
        if (e.key === "Enter") (runCmd("formatFont", inp.value), focusGrid())
      })
      return h("span.ds-fontwrap", inp, dl)
    }
    if (spec.type === "size") {
      const inp = h("input.ds-rsel.size", { list: "ds-sizes", "aria-label": t("Font size", "حجم الخط"), inputmode: "decimal" })
      inp.dataset.role = "size"
      const dl = h("datalist#ds-sizes", SIZES.map((s) => h("option", { value: s })))
      const go = () => {
        const n = clamp(Number(inp.value), 1, 409)
        if (n) applyFmt({ fs: n === 11 ? null : n })
      }
      inp.addEventListener("change", go)
      inp.addEventListener("keydown", (e) => {
        e.stopPropagation()
        if (e.key === "Enter") (go(), focusGrid())
      })
      return h("span", inp, dl)
    }
    if (spec.type === "numfmt") {
      const s = h("select.ds-rsel.numfmt", { "aria-label": t("Number format", "تنسيق الأرقام") })
      s.dataset.role = "numfmt"
      for (const p of NUMBER_PRESETS()) s.append(h("option", { value: p.id }, p.label))
      s.append(h("option", { value: "more" }, t("More number formats…", "تنسيقات أرقام أخرى…")))
      s.addEventListener("change", () => {
        if (s.value === "more") return formatCellsDialog("number")
        const p = NUMBER_PRESETS().find((x) => x.id === s.value)
        setNumberFormat(p?.nf)
        focusGrid()
      })
      return s
    }
    if (spec.type === "scale") {
      const s = h("select.ds-rsel", { "aria-label": t("Scale", "المقياس") })
      s.dataset.role = "scale"
      for (const v of [["auto", t("Automatic", "تلقائي")], ["width", t("Fit width", "احتواء العرض")], ["page", t("Fit one page", "صفحة واحدة")], ["50", "50%"], ["75", "75%"], ["100", "100%"], ["125", "125%"]]) s.append(h("option", { value: v[0] }, v[1]))
      s.addEventListener("change", () => setPrint(s.value === "width" ? { fitW: 1, fitH: 0, scale: null } : s.value === "page" ? { fitW: 1, fitH: 1, scale: null } : s.value === "auto" ? { fitW: 0, fitH: 0, scale: null } : { fitW: 0, fitH: 0, scale: +s.value }))
      return s
    }
    return cmdButton(spec)
  }
  function cmdButton(spec) {
    const c = C[spec.cmd]
    if (!c) return h("span")
    const label = typeof spec.label === "function" ? spec.label() : spec.label === true || spec.big ? c.label : null
    const tip = (spec.tip || c.label) + (c.key ? ` (${keyLabel(c.key)})` : "")
    const b = h("button.ds-rb" + (spec.big ? ".big" : "") + (label ? ".lab" : ""), { type: "button", title: tip, "aria-label": spec.tip || c.label }, h("span", { html: icon(spec.icon || c.icon) }), label ? h("em", label) : null)
    b.dataset.cmd = spec.cmd
    b.addEventListener("click", (e) => {
      if (spec.cmd === "formatPainter" && e.detail === 2) return runCmd("formatPainter", true)
      runCmd(spec.cmd, spec.arg)
      if (!["insertFunction", "find", "replace", "goto"].includes(spec.cmd)) focusGrid()
    })
    if (spec.cmd === "formatPainter") b.addEventListener("dblclick", () => runCmd("formatPainter", true))
    return b
  }
  // Like Excel, the ribbon gives up words before it scrolls: first the labels of the
  // small buttons, then the big buttons shrink to icons. Every button keeps its title.
  function fitRibbon() {
    const rb = ui.ribbon
    if (!rb) return
    rb.classList.remove("rb-c1", "rb-c2")
    if (ui.root.classList.contains("ds-narrow") || !rb.clientWidth) return
    for (const level of ["rb-c1", "rb-c2"]) {
      if (rb.scrollWidth <= rb.clientWidth + 1) return
      rb.classList.add(level)
    }
  }
  function renderRibbon() {
    const tabs = [...RIBBON(), ...contextTabs()]
    const tab = tabs.find((x) => x.id === ribbonTab) || tabs[0]
    ui.ribbon.innerHTML = ""
    for (const g of tab.groups) {
      const items = h("div.ds-gitems")
      for (const it of g.items) {
        if (it && it.col) {
          items.append(h("div.ds-col", it.col.map((x) => btnFor(x))))
          continue
        }
        if (Array.isArray(it)) {
          // a column of rows or a single row
          const isCol = it.length && it.every((x) => typeof x === "string" && x[0] === "+")
          const box = h(isCol ? "div.ds-col" : "div.ds-row")
          for (const x of it) box.append(btnFor(x))
          items.append(box)
        } else items.append(btnFor(it))
      }
      // rows inside a group stack vertically when the group has several row arrays
      const rowsOnly = g.items.every((x) => Array.isArray(x) && !x.every((y) => typeof y === "string" && y[0] === "+"))
      if (rowsOnly) items.classList.add("stack")
      const group = h("section.ds-group", { "aria-label": g.label }, items, h("footer", h("span", g.label), g.launcher ? h("button.ds-launch", { type: "button", title: g.label + "…", html: icon("resize"), on: { click: g.launcher } }) : null))
      ui.ribbon.append(group)
    }
    updateRibbonState()
    fitRibbon()
  }
  function updateRibbonState() {
    return staleOk(ribbonStateNow)
  }
  function ribbonStateNow() {
    if (!ui.ribbon || !sh) return
    // every active() check reads the active cell's style; work it out once for the whole pass
    styleMemo = lookAt(sel.r, sel.c).st
    try {
      ribbonStatePass()
    } finally {
      styleMemo = null
    }
  }
  /* The quick access toolbar's buttons carry data-cmd too, so this pass updates them as well;
     renderQat() is needed only when the toolbar's contents change. */
  function ribbonStatePass() {
    for (const b of ui.root.querySelectorAll("[data-cmd]")) {
      const c = C[b.dataset.cmd]
      if (!c) continue
      if (c.active) b.classList.toggle("on", !!c.active())
      const dis = (c.enabled && !c.enabled()) || (c.write && readOnlyNow())
      b.disabled = !!dis
    }
    const st = activeStyle()
    const font = ui.ribbon.querySelector('[data-role="font"]')
    if (font && host.activeElement !== font) font.value = st.ff || docTheme().font
    const size = ui.ribbon.querySelector('[data-role="size"]')
    if (size && host.activeElement !== size) size.value = st.fs || 11
    const nf = ui.ribbon.querySelector('[data-role="numfmt"]')
    if (nf) {
      const p = NUMBER_PRESETS().find((x) => (x.nf || null) === (st.nf || null))
      nf.value = p ? p.id : st.nf ? "more" : "general"
      if (!p && st.nf) nf.options[nf.options.length - 1].textContent = t("Custom", "مخصص")
    }
    const scale = ui.ribbon.querySelector('[data-role="scale"]')
    if (scale) scale.value = sh.print?.fitW && sh.print?.fitH ? "page" : sh.print?.fitW ? "width" : sh.print?.scale ? String(sh.print.scale) : "auto"
    paintSwatches()
  }
  function paintSwatches() {
    for (const [k, def] of [["fontColor", "#c00000"], ["fillColor", "#ffff00"]]) {
      const el = ui.root.querySelector(`[data-color="${k}"] .ds-swatch`)
      if (el) el.style.stroke = readPref(k, def)
    }
  }
  let ctxTabsKey = ""
  function updateContextTabs() {
    const key = contextTabs()
      .map((x) => x.id)
      .join(",")
    if (key === ctxTabsKey) return
    ctxTabsKey = key
    if (key.includes("tabledesign") && ctxTabsKey && ribbonTab === "home" && false) ribbonTab = "tabledesign"
    renderTabs()
    renderRibbon()
  }
  // display only, so a background recalculation keeps running while the selection moves
  selListeners.push(() =>
    staleOk(() => {
      updateContextTabs()
      updateRibbonState()
      if (!edit.active) updateFormulaBar()
      updateStats()
      placeWidgets()
      const v = wb.getValue(sh.id, sel.r, sel.c)
      const g = lastRange()
      announce((g.r1 !== g.r2 || g.c1 !== g.c2 ? rangeText(g) + ", " : "") + addr(sel.r, sel.c) + ": " + (v == null ? t("blank", "فارغة") : displayOf(sh, sel.r, sel.c)) + (sh.get(sel.r, sel.c)?.f ? ", " + t("formula", "صيغة") + " =" + sh.get(sel.r, sel.c).f : ""))
      sync.presence()
    })
  )

  /* ---------- quick access toolbar ---------- */
  const QAT_ALL = ["save", "undo", "redo", "print", "sortAZ", "sortZA", "filter", "autoSum", "chart", "insertFunction", "find", "formatPainter", "freezePanes", "showFormulas", "fullscreen", "share", "calcNow", "versions"]
  let qatPref = readPref("qat", ["save", "undo", "redo"])
  function renderQat() {
    ui.qat.innerHTML = ""
    for (const id of qatPref) if (C[id]) ui.qat.append(cmdButton({ cmd: id }))
    const more = h("button.ds-rb.more", { type: "button", title: t("Customize quick access toolbar", "تخصيص شريط أدوات الوصول السريع"), html: icon("down") })
    more.addEventListener("click", () =>
      menu(
        [
          { head: t("Show these commands", "إظهار هذه الأوامر") },
          ...QAT_ALL.map((id) => ({
            label: C[id].label,
            checked: qatPref.includes(id),
            keep: true,
            run: () => {
              qatPref = qatPref.includes(id) ? qatPref.filter((x) => x !== id) : [...qatPref, id]
              writePref("qat", qatPref)
              renderQat()
              updateRibbonState()
              more.click()
            },
          })),
          "-",
          { label: t("Customize toolbar…", "تخصيص شريط الأدوات…"), run: () => customizeQat() },
        ],
        more
      )
    )
    ui.qat.append(more)
    for (const b of ui.qat.querySelectorAll("[data-cmd]")) {
      const c = C[b.dataset.cmd]
      if (c?.enabled) b.disabled = !c.enabled()
      if (c?.active) b.classList.toggle("on", !!c.active())
    }
  }
  function customizeQat() {
    const list = h("div.ds-qatlist")
    const draw = () => {
      list.innerHTML = ""
      const all = [...new Set([...qatPref, ...Object.keys(C).filter((id) => C[id].icon && !["backstage", "contextMenu", "tellMe", "cfMenu"].includes(id))])]
      for (const id of all) {
        const row = h("div.ds-qatrow", check(C[id].label, qatPref.includes(id), { "data-id": id }))
        if (qatPref.includes(id)) {
          const up = h("button.ds-icon", { type: "button", title: t("Move up", "نقل لأعلى"), html: icon("up") })
          up.addEventListener("click", () => {
            const i = qatPref.indexOf(id)
            if (i > 0) [qatPref[i - 1], qatPref[i]] = [qatPref[i], qatPref[i - 1]]
            draw()
          })
          row.append(up)
        }
        row.querySelector("input").addEventListener("change", (e) => {
          qatPref = e.target.checked ? [...qatPref, id] : qatPref.filter((x) => x !== id)
          draw()
        })
        list.append(row)
      }
    }
    draw()
    dialog({ title: t("Customize the quick access toolbar", "تخصيص شريط أدوات الوصول السريع"), body: list, buttons: [{ label: t("Reset", "إعادة تعيين"), left: true, action: () => ((qatPref = ["save", "undo", "redo"]), draw(), false) }, { label: t("Done", "تم"), primary: true, action: () => (writePref("qat", qatPref), renderQat()) }] })
  }

  /* ---------- keyboard shortcuts ---------- */
  function keyString(e) {
    let k = e.key
    if (k === " ") k = "Space"
    if (k.length === 1) k = k.toUpperCase()
    if (k === "+" && !e.shiftKey) k = "="
    return (e.ctrlKey || e.metaKey ? "Ctrl+" : "") + (e.altKey ? "Alt+" : "") + (e.shiftKey ? "Shift+" : "") + k
  }
  let shortcutMap = null
  function shortcut(e) {
    if (!shortcutMap) {
      shortcutMap = new Map()
      for (const c of Object.values(C)) if (c.key) shortcutMap.set(c.key.toUpperCase(), c.id)
      // alternates
      shortcutMap.set("CTRL+SHIFT+Z", "redo")
      shortcutMap.set("CTRL+SHIFT+=", "insertCells")
      shortcutMap.set("CTRL+SHIFT++", "insertCells")
      shortcutMap.set("CTRL+=", "zoomIn")
      shortcutMap.set("CTRL+F5", "refreshAll")
      shortcutMap.set("ALT+SHIFT+=", "autoSum")
      shortcutMap.set("F5", "goto")
      shortcutMap.set("CTRL+SHIFT+F", "formatCells")
      shortcutMap.set("CTRL+SHIFT+&", "borders")
      shortcutMap.set("CTRL+SHIFT+:", "insertTime")
      shortcutMap.set("CTRL+SHIFT+;", "insertTime")
      shortcutMap.set("CTRL+SHIFT+~", "numberFormat")
      shortcutMap.set("CTRL+2", "bold")
      shortcutMap.set("CTRL+3", "italic")
      shortcutMap.set("CTRL+4", "underline")
      shortcutMap.set("CTRL+`", "showFormulas")
      shortcutMap.set("CTRL+SHIFT+4", "currency")
      shortcutMap.set("CTRL+SHIFT+5", "percent")
      shortcutMap.set("CTRL+SHIFT+1", "comma")
      shortcutMap.set("CTRL+SHIFT+3", "dateFormat")
      shortcutMap.set("CTRL+SHIFT+2", "timeFormat")
      shortcutMap.set("CTRL+SHIFT+7", "borders")
      shortcutMap.set("CTRL+SHIFT+9", "unhideRows")
      shortcutMap.set("CTRL+SHIFT+0", "unhideCols")
      shortcutMap.set("ALT+ARROWDOWN", "")
      shortcutMap.set("CONTEXTMENU", "contextMenu")
    }
    const k = keyString(e).toUpperCase()
    let id = shortcutMap.get(k)
    if (!id && /^CTRL\+SHIFT\+/.test(k)) id = shortcutMap.get(k.replace("SHIFT+", ""))
    if (!id) return false
    if (id === "numberFormat") runCmd(id, null)
    else if (id === "borders") runCmd("borders", "outside")
    else runCmd(id)
    return true
  }
  function shortcutsDialog() {
    const rows = Object.values(C)
      .filter((c) => c.key)
      .map((c) => `<tr><td>${esc(c.label)}</td><td><kbd>${esc(keyLabel(c.key))}</kbd></td></tr>`)
    const nav = [
      [t("Move to edge of data", "الانتقال إلى حافة البيانات"), MOD + "+Arrow"],
      [t("Extend selection", "توسيع التحديد"), "Shift+Arrow"],
      [t("Edit cell", "تحرير الخلية"), "F2"],
      [t("New line in cell", "سطر جديد في الخلية"), "Alt+Enter"],
      [t("Fill selection with entry", "تعبئة التحديد بالإدخال"), MOD + "+Enter"],
      [t("Absolute/relative reference", "مرجع مطلق/نسبي"), "F4"],
      [t("Select column / row", "تحديد عمود / صف"), MOD + "+Space / Shift+Space"],
      [t("Next / previous sheet", "الورقة التالية / السابقة"), MOD + "+PgDn / PgUp"],
      [t("Pick from list", "اختيار من القائمة"), "Alt+↓"],
    ].map(([a, b]) => `<tr><td>${esc(a)}</td><td><kbd>${esc(b)}</kbd></td></tr>`)
    dialog({ title: t("Keyboard shortcuts", "اختصارات لوحة المفاتيح"), body: `<table class="ds-table">${[...nav, ...rows].join("")}</table>`, wide: true, buttons: [{ label: t("Close", "إغلاق"), primary: true }] })
  }

  /* ---------- context menus ---------- */
  function openContextMenu(at) {
    const p = at || (G ? { stage: true, x: (xOf(sel.c) + sh.cols.size(sel.c)) * G.z, y: yOf(sel.r) * G.z } : { x: 100, y: 100 })
    const g = lastRange()
    const items = []
    const ro = readOnlyNow()
    items.push({ label: t("Cut", "قص"), icon: "cut", kbd: MOD + "+X", disabled: ro, run: () => runCmd("cut") }, { label: t("Copy", "نسخ"), icon: "copy", kbd: MOD + "+C", run: () => runCmd("copy") }, { label: t("Paste", "لصق"), icon: "paste", kbd: MOD + "+V", disabled: ro, run: () => runCmd("paste") }, { label: t("Paste special", "لصق خاص"), icon: "paste", disabled: ro, sub: pasteItems }, "-")
    if (isWholeCols(g)) items.push({ label: t("Insert columns", "إدراج أعمدة"), icon: "cols", disabled: ro, run: () => runCmd("insertColsLeft") }, { label: t("Delete columns", "حذف أعمدة"), icon: "cols", disabled: ro, run: () => runCmd("deleteCols") }, { label: t("Clear contents", "مسح المحتويات"), icon: "eraser", disabled: ro, run: () => runCmd("clearContents") }, "-", { label: t("Column width…", "عرض العمود…"), disabled: ro, run: () => runCmd("colWidth") }, { label: t("AutoFit", "احتواء تلقائي"), disabled: ro, run: () => runCmd("autofitCols") }, { label: t("Hide", "إخفاء"), icon: "eyeOff", disabled: ro, run: () => runCmd("hideCols") }, { label: t("Unhide", "إظهار"), icon: "eye", disabled: ro, run: () => runCmd("unhideCols") }, { label: t("Group", "تجميع"), icon: "group", disabled: ro, run: () => runCmd("group") })
    else if (isWholeRows(g)) items.push({ label: t("Insert rows", "إدراج صفوف"), icon: "rows", disabled: ro, run: () => runCmd("insertRowsAbove") }, { label: t("Delete rows", "حذف صفوف"), icon: "rows", disabled: ro, run: () => runCmd("deleteRows") }, { label: t("Clear contents", "مسح المحتويات"), icon: "eraser", disabled: ro, run: () => runCmd("clearContents") }, "-", { label: t("Row height…", "ارتفاع الصف…"), disabled: ro, run: () => runCmd("rowHeight") }, { label: t("AutoFit", "احتواء تلقائي"), disabled: ro, run: () => runCmd("autofitRows") }, { label: t("Hide", "إخفاء"), icon: "eyeOff", disabled: ro, run: () => runCmd("hideRows") }, { label: t("Unhide", "إظهار"), icon: "eye", disabled: ro, run: () => runCmd("unhideRows") }, { label: t("Group", "تجميع"), icon: "group", disabled: ro, run: () => runCmd("group") })
    else {
      items.push(
        { label: t("Insert…", "إدراج…"), icon: "insert", disabled: ro, sub: [{ label: t("Rows above", "صفوف أعلى"), run: () => runCmd("insertRowsAbove") }, { label: t("Rows below", "صفوف أسفل"), run: () => runCmd("insertRowsBelow") }, { label: t("Columns left", "أعمدة يسارًا"), run: () => runCmd("insertColsLeft") }, { label: t("Columns right", "أعمدة يمينًا"), run: () => runCmd("insertColsRight") }, { label: t("Cells…", "خلايا…"), run: () => runCmd("insertCells") }] },
        { label: t("Delete…", "حذف…"), icon: "delete", disabled: ro, sub: [{ label: t("Rows", "صفوف"), run: () => runCmd("deleteRows") }, { label: t("Columns", "أعمدة"), run: () => runCmd("deleteCols") }, { label: t("Cells…", "خلايا…"), run: () => runCmd("deleteCells") }] },
        { label: t("Clear contents", "مسح المحتويات"), icon: "eraser", kbd: "Del", disabled: ro, run: () => runCmd("clearContents") },
        "-",
        { label: t("Filter", "تصفية"), icon: "filter", disabled: ro, sub: [{ label: t("Filter by selected cell's value", "تصفية حسب قيمة الخلية"), run: () => filterByValue() }, { label: t("Clear filter", "مسح التصفية"), run: () => runCmd("clearFilter") }, { label: t("Toggle filter", "تبديل التصفية"), run: () => runCmd("filter") }] },
        { label: t("Sort", "فرز"), icon: "sort", disabled: ro, sub: [{ label: t("Sort A to Z", "فرز من أ إلى ي"), run: () => runCmd("sortAZ") }, { label: t("Sort Z to A", "فرز من ي إلى أ"), run: () => runCmd("sortZA") }, { label: t("Custom sort…", "فرز مخصص…"), run: () => runCmd("sortCustom") }] },
        "-"
      )
      const hasComment = sh.comments.has(ck(sel.r, sel.c))
      items.push({ label: hasComment ? t("Edit comment", "تحرير التعليق") : t("New comment", "تعليق جديد"), icon: "comment", disabled: ro, run: () => runCmd("comment") })
      if (hasComment) items.push({ label: t("Delete comment", "حذف التعليق"), icon: "trash", disabled: ro, run: () => runCmd("deleteComment") })
      const rule = dvFor(sh, sel.r, sel.c)
      if (rule?.type === "list") items.push({ label: t("Pick from drop-down list", "اختيار من القائمة المنسدلة"), icon: "list", run: () => openCellDropdown() })
      items.push({ label: t("Format cells…", "تنسيق الخلايا…"), icon: "format", kbd: MOD + "+1", disabled: ro, run: () => runCmd("formatCells") }, { label: t("Define name…", "تعريف اسم…"), icon: "name", disabled: ro, run: () => runCmd("defineName") }, { label: t("Link…", "ارتباط…"), icon: "link", kbd: MOD + "+K", disabled: ro, run: () => runCmd("link") })
      if (wb.tableAt(sh.id, sel.r, sel.c)) items.push("-", { label: t("Table", "جدول"), icon: "table", sub: () => tableContextItems() })
    }
    menu(items, p)
  }
  function onContextMenu(e) {
    e.preventDefault()
    if (touchMode && e.pointerType !== "mouse") return
    const b = ui.stage.getBoundingClientRect()
    openContextMenu({ stage: true, x: e.clientX - b.left, y: e.clientY - b.top })
  }

  /* ---------- sheet tabs ---------- */
  function renderSheetTabs() {
    if (!ui.sheetTabs || !wb) return
    ui.sheetTabs.innerHTML = ""
    for (const s of wb.sheets) {
      if (s.hidden) continue
      const tab = h("button.ds-sheettab" + (s === sh ? ".on" : ""), { role: "tab", type: "button", "aria-selected": String(s === sh), draggable: "true", title: s.name + (s.protect ? " · " + t("protected", "محمية") : "") }, s.protect ? h("span.ds-lock", { html: icon("lock") }) : null, h("span", s.name))
      if (s.color) tab.style.setProperty("--tab", s.color)
      tab.addEventListener("click", () => {
        if (edit.active && editingFormula()) {
          activateSheet(s.id)
          return
        }
        activateSheet(s.id)
        focusGrid()
      })
      tab.addEventListener("dblclick", () => inlineRename(tab, s))
      tab.addEventListener("contextmenu", (e) => {
        e.preventDefault()
        activateSheet(s.id)
        sheetTabMenu(tab, s)
      })
      tab.addEventListener("dragstart", (e) => {
        e.dataTransfer.setData("text/x-durar-sheet", String(s.id))
        e.dataTransfer.effectAllowed = "move"
      })
      tab.addEventListener("dragover", (e) => {
        if (e.dataTransfer.types.includes("text/x-durar-sheet")) {
          e.preventDefault()
          tab.classList.add("drop")
        }
      })
      tab.addEventListener("dragleave", () => tab.classList.remove("drop"))
      tab.addEventListener("drop", (e) => {
        e.preventDefault()
        tab.classList.remove("drop")
        const id = Number(e.dataTransfer.getData("text/x-durar-sheet"))
        if (id && id !== s.id) moveSheet(id, wb.sheetIndex(s.id))
      })
      ui.sheetTabs.append(tab)
    }
    ui.sheetTabs.querySelector(".on")?.scrollIntoView({ block: "nearest", inline: "nearest" })
  }
  function inlineRename(tab, s) {
    if (readOnlyNow() || wb.protect?.structure) return
    const inp = h("input.ds-tabinput", { value: s.name, "aria-label": t("Sheet name", "اسم الورقة") })
    tab.replaceWith(inp)
    inp.focus()
    inp.select()
    let done = false
    const finish = (save) => {
      if (done) return
      done = true
      if (save && inp.value.trim() && inp.value.trim() !== s.name) renameSheet(s.id, inp.value)
      else renderSheetTabs()
      focusGrid()
    }
    inp.addEventListener("keydown", (e) => {
      e.stopPropagation()
      if (e.key === "Enter") finish(true)
      if (e.key === "Escape") finish(false)
    })
    inp.addEventListener("blur", () => finish(true))
  }
  function sheetTabMenu(at, s) {
    const ro = readOnlyNow()
    menu(
      [
        { label: t("Insert sheet", "إدراج ورقة"), icon: "plus", disabled: ro, run: () => insertSheet(wb.sheetIndex(s.id) + 1) },
        { label: t("Delete", "حذف"), icon: "trash", disabled: ro, run: () => deleteSheet(s.id) },
        { label: t("Rename", "إعادة تسمية"), icon: "edit", disabled: ro, run: () => renameSheet(s.id) },
        { label: t("Duplicate", "تكرار"), icon: "duplicate", disabled: ro, run: () => duplicateSheet(s.id) },
        { label: t("Move or copy…", "نقل أو نسخ…"), icon: "duplicate", disabled: ro, run: () => moveCopyDialog(s.id) },
        { label: t("Tab color", "لون علامة التبويب"), icon: "color", disabled: ro, run: () => later(() => colorPicker(at, (c) => setSheetMeta(s.id, "color", c, t("Tab color", "لون علامة التبويب")), { none: true }), 0) },
        "-",
        { label: t("Hide", "إخفاء"), icon: "eyeOff", disabled: ro, run: () => runCmd("hideSheet") },
        { label: t("Unhide…", "إظهار…"), icon: "eye", disabled: ro || !wb.sheets.some((x) => x.hidden), run: () => runCmd("unhideSheet") },
        { label: s.protect ? t("Unprotect sheet…", "إلغاء حماية الورقة…") : t("Protect sheet…", "حماية الورقة…"), icon: "lock", disabled: ro, run: () => runCmd("protectSheet") },
      ],
      at
    )
  }
  function allSheetsMenu(at) {
    menu(
      wb.sheets.map((s) => ({
        label: s.name + (s.hidden ? " (" + t("hidden", "مخفية") + ")" : ""),
        checked: s === sh,
        run: () => {
          if (s.hidden) setSheetMeta(s.id, "hidden", false, t("Unhide sheet", "إظهار ورقة"))
          activateSheet(s.id)
        },
      })),
      at
    )
  }

  /* ======================================================================
     Dialogs: format cells, paste special, find & replace, go to, names,
     sorting, protection, comments, conditional formatting, validation,
     formula auditing and smaller prompts.
     ====================================================================== */
  function tabsUI(tabs, active) {
    const head = h("div.ds-dtabs", { role: "tablist" })
    const bodies = h("div.ds-dpanes")
    for (const [id, label, el] of tabs) {
      const b = h("button.ds-dtab", { type: "button", role: "tab", "aria-selected": String(id === active) }, label)
      const pane = h("div.ds-dpane", { hidden: id !== active, role: "tabpanel" }, el)
      b.addEventListener("click", () => {
        head.querySelectorAll(".ds-dtab").forEach((x) => x.setAttribute("aria-selected", "false"))
        bodies.querySelectorAll(".ds-dpane").forEach((x) => (x.hidden = true))
        b.setAttribute("aria-selected", "true")
        pane.hidden = false
      })
      head.append(b)
      bodies.append(pane)
    }
    return h("div", head, bodies)
  }

  /* ---------- Format Cells ---------- */
  function formatCellsDialog(tab = "number") {
    const st = { ...styleOf(sh.styleIdAt(sel.r, sel.c)) }
    const v = wb.getValue(sh.id, sel.r, sel.c)
    const sample = typeof v === "number" || typeof v === "string" ? v : 1234.5678
    const patch = {}
    const set = (k, val) => {
      patch[k] = val
      st[k] = val
      preview()
    }
    // Number
    const cats = [
      ["general", t("General", "عام")],
      ["number", t("Number", "رقم")],
      ["currency", t("Currency", "عملة")],
      ["accounting", t("Accounting", "محاسبي")],
      ["date", t("Date", "تاريخ")],
      ["time", t("Time", "وقت")],
      ["percent", t("Percentage", "نسبة مئوية")],
      ["fraction", t("Fraction", "كسر")],
      ["scientific", t("Scientific", "علمي")],
      ["text", t("Text", "نص")],
      ["special", t("Special", "خاص")],
      ["custom", t("Custom", "مخصص")],
    ]
    const catList = h("select.ds-input.ds-catlist", { size: 12 }, cats.map(([k, l]) => h("option", { value: k }, l)))
    const opts = h("div.ds-nfopts")
    const prev = h("div.ds-nfprev")
    const custom = input(st.nf || "General", { spellcheck: "false" })
    const guessCat = (nf) => {
      if (!nf) return "general"
      const f = compileFormat(nf)
      if (nf === "@") return "text"
      if (f?.isDate) return /[hs]/i.test(nf.replace(/\[[^\]]*\]|"[^"]*"/g, "")) && !/[dy]/i.test(nf.replace(/\[[^\]]*\]|"[^"]*"/g, "")) ? "time" : "date"
      if (f?.isPct) return "percent"
      if (/E[+-]/i.test(nf)) return "scientific"
      if (/\?\/|#\s\?/.test(nf)) return "fraction"
      if (/_\(|\*/.test(nf)) return "accounting"
      if (new RegExp("\\[\\$|" + CFG.curSym.replace(/[.*+?^${}()|[\]\\]/g, "\\$&") + "|[$€£¥₹]").test(nf)) return "currency"
      if (/^#,##0(\.0+)?$|^0(\.0+)?$/.test(nf)) return "number"
      return "custom"
    }
    let cat = guessCat(st.nf)
    catList.value = cat
    const decs = (nf) => ((nf || "").split(";")[0].split(".")[1] || "").replace(/[^0#]/g, "").length
    function numOpts() {
      opts.innerHTML = ""
      const nf = st.nf
      const d = input(String(nf ? decs(nf) : 2), { type: "number", min: 0, max: 30, style: { width: "80px" } })
      const sep = check(t("Use 1000 separator (,)", "استخدام فاصل الآلاف (,)"), /,/.test(nf || "#,##0"))
      const neg = select(
        [
          ["-", "-1,234.10"],
          ["red", "1,234.10 (" + t("red", "أحمر") + ")"],
          ["paren", "(1,234.10)"],
          ["parenred", "(1,234.10) (" + t("red", "أحمر") + ")"],
        ],
        /\[Red\]\(/.test(nf || "") ? "parenred" : /\[Red\]/.test(nf || "") ? "red" : /;\(/.test(nf || "") ? "paren" : "-"
      )
      const symList = [...new Set([CFG.curSym, "SAR", "$", "€", "£", "AED", "KWD", "EGP", "¥", "₹"])]
      const sym = select(symList, symList.find((s) => (nf || "").includes(s)) || CFG.curSym)
      const build = () => {
        const n = clamp(+d.value || 0, 0, 30)
        const dd = n ? "." + "0".repeat(n) : ""
        let body = (sep.querySelector("input").checked || cat === "currency" || cat === "accounting" ? "#,##0" : "0") + dd
        if (cat === "currency") body = currencyFormat(sym.value, n)
        if (cat === "accounting") return `_("${sym.value}" * #,##0${dd}_);_("${sym.value}" * (#,##0${dd});_("${sym.value}" * "-"${"?".repeat(n)}_);_(@_)`
        if (cat === "percent") return "0" + dd + "%"
        if (cat === "scientific") return "0" + dd + "E+00"
        const ng = neg.value
        if (ng === "red") return body + ";[Red]" + body
        if (ng === "paren") return body + ";(" + body + ")"
        if (ng === "parenred") return body + ";[Red](" + body + ")"
        return body
      }
      const apply = () => set("nf", build())
      for (const el of [d, sep, neg, sym]) el.addEventListener("change", apply)
      d.addEventListener("input", apply)
      opts.append(field(t("Decimal places", "المنازل العشرية"), d))
      if (cat === "number") opts.append(sep, field(t("Negative numbers", "الأرقام السالبة"), neg))
      if (cat === "currency" || cat === "accounting") opts.append(field(t("Symbol", "الرمز"), sym))
      if (cat === "currency") opts.append(field(t("Negative numbers", "الأرقام السالبة"), neg))
      if (!nf || guessCat(nf) !== cat) apply()
    }
    function listOpts(list) {
      opts.innerHTML = ""
      const l = h("select.ds-input", { size: 8 }, list.map((f) => h("option", { value: f, selected: f === st.nf }, formatValue(typeof sample === "number" ? sample : 46000.5625, f).t + "    (" + f + ")")))
      l.addEventListener("change", () => set("nf", l.value))
      opts.append(l)
      if (!list.includes(st.nf)) set("nf", list[0])
    }
    function catChanged() {
      cat = catList.value
      if (cat === "general") {
        opts.innerHTML = `<p class="ds-note">${t("General format cells have no specific number format.", "الخلايا ذات التنسيق العام ليس لها تنسيق أرقام محدد.")}</p>`
        set("nf", null)
      } else if (["number", "currency", "accounting", "percent", "scientific"].includes(cat)) numOpts()
      else if (cat === "date") listOpts([CFG.dateFmt, "yyyy-mm-dd", "dd/mm/yyyy", "mm/dd/yyyy", "d-mmm-yy", "d mmmm yyyy", "dddd, mmmm d, yyyy", "mmm-yy", "mmmm yyyy", "dd/mm/yyyy hh:mm", "yyyy-mm-dd hh:mm:ss", "[$-ar]dddd d mmmm yyyy"])
      else if (cat === "time") listOpts(["h:mm", "hh:mm:ss", "h:mm AM/PM", "h:mm:ss AM/PM", "[h]:mm:ss", "mm:ss.0"])
      else if (cat === "fraction") listOpts(["# ?/?", "# ??/??", "# ???/???", "# ?/2", "# ?/4", "# ?/8", "# ??/16", "# ?/10", "# ??/100"])
      else if (cat === "text") {
        opts.innerHTML = `<p class="ds-note">${t("Text format cells are treated as text even when a number is in the cell.", "خلايا تنسيق النص تُعامل كنص حتى عند وجود رقم فيها.")}</p>`
        set("nf", "@")
      } else if (cat === "special") listOpts(["00000", "00000-0000", "(###) ###-####", "000-00-0000", "+966 0 000 0000", "0000 0000 0000 0000"])
      else {
        opts.innerHTML = ""
        const used = new Set(["General", "0", "0.00", "#,##0", "#,##0.00", "0%", "0.00%", "0.00E+00", "# ?/?", "@", CFG.dateFmt, "h:mm AM/PM", curFmt(), "#,##0;(#,##0)", '#,##0.00;[Red]-#,##0.00', '0;-0;"—"'])
        for (const s of wb.sheets) for (const c of s.cells.values()) if (c.s && styleOf(c.s).nf) used.add(styleOf(c.s).nf)
        const l = h("select.ds-input", { size: 8 }, [...used].map((f) => h("option", { value: f, selected: f === st.nf }, f)))
        l.addEventListener("change", () => {
          custom.value = l.value
          set("nf", l.value === "General" ? null : l.value)
        })
        custom.value = st.nf || "General"
        custom.addEventListener("input", () => set("nf", /^general$/i.test(custom.value) ? null : custom.value))
        opts.append(field(t("Type", "النوع"), custom), l)
      }
    }
    catList.addEventListener("change", catChanged)
    const numPane = h("div.ds-nfpane", catList, h("div", h("div.ds-label", t("Sample", "عينة")), prev, opts))

    // Alignment
    const ha = select([["general", t("General", "عام")], ["left", t("Left", "يسار")], ["center", t("Center", "توسيط")], ["right", t("Right", "يمين")], ["fill", t("Fill", "تعبئة")], ["justify", t("Justify", "ضبط")]], st.ha || "general")
    ha.addEventListener("change", () => set("ha", ha.value === "general" ? null : ha.value))
    const va = select([["bottom", t("Bottom", "أسفل")], ["middle", t("Center", "توسيط")], ["top", t("Top", "أعلى")]], st.va || "bottom")
    va.addEventListener("change", () => set("va", va.value === "bottom" ? null : va.value))
    const ind = input(String(st.ind || 0), { type: "number", min: 0, max: 15 })
    ind.addEventListener("input", () => set("ind", +ind.value || null))
    const wr = check(t("Wrap text", "التفاف النص"), st.wr)
    wr.querySelector("input").addEventListener("change", (e) => set("wr", e.target.checked ? 1 : null))
    const shk = check(t("Shrink to fit", "تقليص للاحتواء"), st.sh)
    shk.querySelector("input").addEventListener("change", (e) => set("sh", e.target.checked ? 1 : null))
    const mg = check(t("Merge cells", "دمج الخلايا"), !!sh.mergeAt(sel.r, sel.c))
    const rot = input(String(st.rot === 255 ? 0 : st.rot || 0), { type: "number", min: -90, max: 90 })
    rot.addEventListener("input", () => set("rot", clamp(+rot.value || 0, -90, 90) || null))
    const vert = check(t("Vertical text", "نص عمودي"), st.rot === 255)
    vert.querySelector("input").addEventListener("change", (e) => set("rot", e.target.checked ? 255 : null))
    const alignPane = h("div.ds-grid2", field(t("Horizontal", "أفقي"), ha), field(t("Vertical", "عمودي"), va), field(t("Indent", "المسافة البادئة"), ind), field(t("Orientation (degrees)", "الاتجاه (درجات)"), rot), h("div.ds-stack", wr, shk, mg, vert))

    // Font
    const ff = h("input.ds-input", { value: st.ff || docTheme().font, list: "ds-fontlist2" })
    ff.addEventListener("change", () => set("ff", ff.value === docTheme().font ? null : ff.value))
    const fs = h("input.ds-input", { value: st.fs || 11, type: "number", min: 1, max: 409 })
    fs.addEventListener("input", () => set("fs", +fs.value && +fs.value !== 11 ? +fs.value : null))
    const fstyle = select([["", t("Regular", "عادي")], ["i", t("Italic", "مائل")], ["b", t("Bold", "غامق")], ["bi", t("Bold italic", "غامق مائل")]], (st.b ? "b" : "") + (st.i ? "i" : ""))
    fstyle.addEventListener("change", () => {
      set("b", fstyle.value.includes("b") ? 1 : null)
      set("i", fstyle.value.includes("i") ? 1 : null)
    })
    const und = select([["", t("None", "بلا")], ["1", t("Single", "مفرد")], ["2", t("Double", "مزدوج")]], String(st.u || ""))
    und.addEventListener("change", () => set("u", +und.value || null))
    const fc = h("input", { type: "color", value: st.fc || "#000000" })
    fc.addEventListener("input", () => set("fc", fc.value))
    const strike = check(t("Strikethrough", "يتوسطه خط"), st.st)
    strike.querySelector("input").addEventListener("change", (e) => set("st", e.target.checked ? 1 : null))
    const fontPane = h("div.ds-grid2", field(t("Font", "الخط"), h("span", ff, h("datalist#ds-fontlist2", FONTS.map((f) => h("option", { value: f }))))), field(t("Size", "الحجم"), fs), field(t("Style", "النمط"), fstyle), field(t("Underline", "التسطير"), und), field(t("Color", "اللون"), fc), strike)

    // Border
    const bstyle = select(["thin", "medium", "thick", "dashed", "dotted", "double", "hair", "mediumDashed", "dashDot"], borderPref.style)
    const bcolor = h("input", { type: "color", value: borderPref.color })
    const bprev = h("div.ds-bprev")
    const g = lastRange()
    const edges = { top: st.bt, bottom: st.bb, left: st.bl, right: st.br, dd: st.dd, du: st.du }
    const items = []
    const drawB = () => {
      bprev.innerHTML = ""
      for (const k of ["top", "bottom", "left", "right", "dd", "du"]) {
        const b = h("button.ds-bedge." + k + (edges[k] ? ".on" : ""), { type: "button", title: k })
        if (edges[k]) b.style.setProperty("--b", edges[k].split(" ")[1] || "#000")
        b.addEventListener("click", () => {
          edges[k] = edges[k] ? null : bstyle.value + " " + bcolor.value
          drawB()
        })
        bprev.append(b)
      }
      bprev.append(h("span.ds-btext", "Text"))
    }
    drawB()
    const preset = (k) =>
      h("button.ds-btn", {
        type: "button",
        on: {
          click: () => {
            const line = bstyle.value + " " + bcolor.value
            if (k === "none") for (const e of Object.keys(edges)) edges[e] = null
            if (k === "outline") Object.assign(edges, { top: line, bottom: line, left: line, right: line })
            if (k === "inside") items.push("inside")
            drawB()
          },
        },
      }, { none: t("None", "بلا"), outline: t("Outline", "خارجي"), inside: t("Inside", "داخلي") }[k])
    const borderPane = h("div.ds-grid2", h("div", field(t("Line style", "نمط الخط"), bstyle), field(t("Color", "اللون"), bcolor), h("div.ds-row", preset("none"), preset("outline"), preset("inside"))), h("div", h("div.ds-label", t("Click the edges of the preview", "انقر حواف المعاينة")), bprev))

    // Fill
    const bg = h("input", { type: "color", value: st.bg || "#ffffff" })
    const noFill = check(t("No fill", "بلا تعبئة"), !st.bg)
    bg.addEventListener("input", () => {
      noFill.querySelector("input").checked = false
      set("bg", bg.value)
    })
    noFill.querySelector("input").addEventListener("change", (e) => set("bg", e.target.checked ? null : bg.value))
    const swatches = h("div.ds-swatches")
    for (const row of themeGrid()) for (const c of row) swatches.append(h("button.ds-swatch", { type: "button", style: { background: c }, title: c, on: { click: () => ((bg.value = c), set("bg", c), (noFill.querySelector("input").checked = false)) } }))
    const fillPane = h("div", noFill, swatches, field(t("More colors", "ألوان أخرى"), bg))

    // Protection
    const locked = check(t("Locked", "مؤمّن"), !st.ul)
    locked.querySelector("input").addEventListener("change", (e) => set("ul", e.target.checked ? null : 1))
    const hidden = check(t("Hidden (hide the formula)", "مخفي (إخفاء الصيغة)"), st.hd)
    hidden.querySelector("input").addEventListener("change", (e) => set("hd", e.target.checked ? 1 : null))
    const protPane = h("div.ds-stack", locked, hidden, h("p.ds-note", t("Locking cells or hiding formulas has no effect until you protect the sheet (Review > Protect Sheet).", "لا يكون لتأمين الخلايا أو إخفاء الصيغ أي تأثير حتى تحمي الورقة (مراجعة > حماية الورقة).")))

    function preview() {
      const f = formatValue(sample, st.nf)
      prev.textContent = typeof sample === "number" || st.nf ? f.t : String(sample)
      prev.style.color = f.c || ""
    }
    catChanged()
    preview()
    const body = tabsUI(
      [
        ["number", t("Number", "رقم"), numPane],
        ["align", t("Alignment", "محاذاة"), alignPane],
        ["font", t("Font", "خط"), fontPane],
        ["border", t("Border", "حد"), borderPane],
        ["fill", t("Fill", "تعبئة"), fillPane],
        ["protect", t("Protection", "حماية"), protPane],
      ],
      tab
    )
    dialog({
      title: t("Format cells", "تنسيق الخلايا"),
      body,
      wide: true,
      buttons: [
        { label: t("Cancel", "إلغاء") },
        {
          label: t("OK", "موافق"),
          primary: true,
          action: () => {
            const ops = []
            if (Object.keys(patch).length) ops.push({ t: "fmt", s: sh.id, items: [{ rects: selRects(), p: patch }] })
            // borders: compare with what the active cell had
            const bpatch = {}
            const map = { top: "bt", bottom: "bb", left: "bl", right: "br", dd: "dd", du: "du" }
            for (const [k, sk] of Object.entries(map)) if ((edges[k] || null) !== (styleOf(sh.styleIdAt(sel.r, sel.c))[sk] || null)) bpatch[sk] = edges[k] || null
            if (Object.keys(bpatch).length) {
              const items2 = []
              for (const gg of sel.ranges) {
                const b2 = boundedRect(gg)
                if ("bt" in bpatch) items2.push({ rects: [[b2.r1, b2.c1, b2.r1, b2.c2]], p: { bt: bpatch.bt } })
                if ("bb" in bpatch) items2.push({ rects: [[b2.r2, b2.c1, b2.r2, b2.c2]], p: { bb: bpatch.bb } })
                if ("bl" in bpatch) items2.push({ rects: [[b2.r1, b2.c1, b2.r2, b2.c1]], p: { bl: bpatch.bl } })
                if ("br" in bpatch) items2.push({ rects: [[b2.r1, b2.c2, b2.r2, b2.c2]], p: { br: bpatch.br } })
                if ("dd" in bpatch || "du" in bpatch) items2.push({ rects: [rectOf(b2)], p: { ...("dd" in bpatch ? { dd: bpatch.dd } : {}), ...("du" in bpatch ? { du: bpatch.du } : {}) } })
              }
              ops.push({ t: "fmt", s: sh.id, items: items2 })
            }
            if (items.includes("inside")) {
              const line = bstyle.value + " " + bcolor.value
              const items3 = []
              for (const gg of sel.ranges) {
                const b2 = boundedRect(gg)
                if (b2.r2 > b2.r1) items3.push({ rects: [[b2.r1, b2.c1, b2.r2 - 1, b2.c2]], p: { bb: line } })
                if (b2.c2 > b2.c1) items3.push({ rects: [[b2.r1, b2.c1, b2.r2, b2.c2 - 1]], p: { br: line } })
              }
              if (items3.length) ops.push({ t: "fmt", s: sh.id, items: items3 })
            }
            borderPref = { style: bstyle.value, color: bcolor.value }
            writePref("border", borderPref)
            if (ops.length) doOps(ops, { label: t("Format cells", "تنسيق الخلايا") })
            const isMerged = !!sh.mergeAt(sel.r, sel.c)
            if (mg.querySelector("input").checked !== isMerged) mergeCells(isMerged ? "unmerge" : "cells")
            void g
          },
        },
      ],
    })
  }

  /* ---------- Paste Special ---------- */
  function pasteSpecialDialog() {
    if (!clip) return toast(t("Copy cells in this workbook first. For other apps use Ctrl+V.", "انسخ خلايا من هذا المصنف أولًا. للتطبيقات الأخرى استخدم Ctrl+V."))
    const what = [
      ["all", t("All", "الكل")],
      ["formulas", t("Formulas", "الصيغ")],
      ["values", t("Values", "القيم")],
      ["formats", t("Formats", "التنسيقات")],
      ["comments", t("Comments", "التعليقات")],
      ["validation", t("Validation", "التحقق")],
      ["noBorders", t("All except borders", "الكل باستثناء الحدود")],
      ["widths", t("Column widths", "عرض الأعمدة")],
    ]
    const ops = [["", t("None", "بلا")], ["add", t("Add", "جمع")], ["sub", t("Subtract", "طرح")], ["mul", t("Multiply", "ضرب")], ["div", t("Divide", "قسمة")]]
    const body = h(
      "div.ds-grid2",
      h("fieldset", h("legend", t("Paste", "لصق")), what.map(([v, l], i) => radio("what", v, l, i === 0))),
      h("div", h("fieldset", h("legend", t("Operation", "عملية")), ops.map(([v, l], i) => radio("op", v, l, i === 0))), check(t("Skip blanks", "تخطي الفراغات"), false, { name: "skip" }), check(t("Transpose", "تبديل"), false, { name: "transpose" }))
    )
    dialog({
      title: t("Paste special", "لصق خاص"),
      body,
      buttons: [
        { label: t("Paste link", "لصق ارتباط"), left: true, action: () => pasteInternal(clip, lastRange(), { link: true }) },
        { label: t("Cancel", "إلغاء") },
        {
          label: t("OK", "موافق"),
          primary: true,
          action: () => {
            const w = body.querySelector('[name="what"]:checked').value
            const op = body.querySelector('[name="op"]:checked').value
            const o = { skipBlanks: body.querySelector('[name="skip"]').checked, transpose: body.querySelector('[name="transpose"]').checked, op: op || null }
            if (w !== "all") o[w === "noBorders" ? "noBorders" : w] = true
            if (w === "noBorders") o.formats = false
            pasteInternal({ ...clip, cut: false }, lastRange(), o)
          },
        },
      ],
    })
  }

  /* ---------- Find & Replace ---------- */
  let findState = { q: "", rep: "", within: "sheet", by: "rows", look: "values", mc: false, whole: false, re: false, pos: null }
  function findDialog(replace) {
    const q = input(findState.q, { placeholder: t("Find what", "البحث عن"), autofocus: true })
    const rep = input(findState.rep, { placeholder: t("Replace with", "الاستبدال بـ") })
    const within = select([["sheet", t("Sheet", "الورقة")], ["book", t("Workbook", "المصنف")], ["sel", t("Selection", "التحديد")]], findState.within)
    const look = select([["values", t("Values", "القيم")], ["formulas", t("Formulas", "الصيغ")], ["comments", t("Comments", "التعليقات")]], findState.look)
    const by = select([["rows", t("By rows", "حسب الصفوف")], ["cols", t("By columns", "حسب الأعمدة")]], findState.by)
    const mc = check(t("Match case", "مطابقة حالة الأحرف"), findState.mc)
    const whole = check(t("Match entire cell contents", "مطابقة محتويات الخلية بالكامل"), findState.whole)
    const re = check(t("Use regular expressions", "استخدام التعابير النمطية"), findState.re)
    const results = h("div.ds-findresults")
    const status = h("p.ds-note")
    const read = () => {
      Object.assign(findState, { q: q.value, rep: rep.value, within: within.value, look: look.value, by: by.value, mc: mc.querySelector("input").checked, whole: whole.querySelector("input").checked, re: re.querySelector("input").checked })
    }
    const body = h("div.ds-find", field(t("Find what", "البحث عن"), q), replace ? field(t("Replace with", "الاستبدال بـ"), rep) : null, h("div.ds-grid3", field(t("Within", "ضمن"), within), field(t("Search", "البحث"), by), field(t("Look in", "البحث في"), look)), h("div.ds-row", mc, whole, re), status, results)
    const d = dialog({
      title: replace ? t("Find and replace", "بحث واستبدال") : t("Find", "بحث"),
      body,
      modeless: true,
      wide: true,
      cls: "find",
      onClose: () => {
        findHits = null
        invalidate()
      },
      buttons: [
        ...(replace
          ? [
              { label: t("Replace all", "استبدال الكل"), left: true, action: () => (read(), replaceAll(status), false) },
              { label: t("Replace", "استبدال"), left: true, action: () => (read(), replaceOne(status), false) },
            ]
          : []),
        {
          label: t("Find all", "بحث عن الكل"),
          action: () => {
            read()
            const hits = findAll()
            findHits = hits.slice(0, 2000)
            invalidate()
            status.textContent = t(`${hits.length} cell(s) found`, `تم العثور على ${hits.length} خلية`)
            results.innerHTML = ""
            const table = h("table.ds-table")
            for (const hit of hits.slice(0, 500)) {
              const tr = h("tr", h("td", wb.sheetName(hit.sid)), h("td", addr(hit.r, hit.c)), h("td", hit.text.slice(0, 80)))
              tr.addEventListener("click", () => {
                if (hit.sid !== sh.id) activateSheet(hit.sid)
                setSel(hit.r, hit.c)
              })
              table.append(tr)
            }
            results.append(table)
            return false
          },
        },
        { label: t("Find next", "بحث عن التالي"), primary: true, action: () => (read(), findNext(status), false) },
      ],
    })
    q.addEventListener("keydown", (e) => {
      if (e.key === "Enter") {
        e.preventDefault()
        read()
        findNext(status)
      }
    })
    return d
  }
  function findMatcher() {
    const s = findState
    if (!s.q) return null
    let re
    try {
      re = s.re ? new RegExp(s.whole ? "^(?:" + s.q + ")$" : s.q, s.mc ? "gu" : "giu") : new RegExp(s.whole ? "^" + wildRe(s.q, false).source + "$" : wildRe(s.q, false).source, s.mc ? "gu" : "giu")
    } catch {
      return null
    }
    return re
  }
  function cellSearchText(sheet, r, c) {
    const cell = sheet.cells.get(ck(r, c))
    if (findState.look === "comments") return sheet.comments.get(ck(r, c))?.thread?.map((m) => m.text).join("\n") || ""
    if (!cell) return ""
    if (findState.look === "formulas" && cell.f != null) return "=" + cell.f
    return displayOf(sheet, r, c)
  }
  function findAll() {
    const re = findMatcher()
    if (!re) return []
    const sheets = findState.within === "book" ? wb.sheets : [sh]
    const hits = []
    for (const sheet of sheets) {
      const keys = findState.look === "comments" ? [...sheet.comments.keys()] : [...sheet.cells.keys()]
      if (sheet.spillOwner.size && findState.look === "values") for (const k of sheet.spillOwner.keys()) keys.push(k)
      const sorted = [...new Set(keys)].sort((a, b) => (findState.by === "cols" ? ckC(a) - ckC(b) || ckR(a) - ckR(b) : a - b))
      for (const k of sorted) {
        const r = ckR(k)
        const c = ckC(k)
        if (findState.within === "sel" && !inSelection(r, c)) continue
        const text = cellSearchText(sheet, r, c)
        re.lastIndex = 0
        if (text && re.test(text)) hits.push({ sid: sheet.id, r, c, text })
      }
    }
    return hits
  }
  function findNext(status) {
    const hits = findAll()
    if (!hits.length) {
      status.textContent = t("We couldn't find what you were looking for.", "لم نتمكن من العثور على ما تبحث عنه.")
      return null
    }
    const cur = { sid: sh.id, r: sel.r, c: sel.c }
    const order = (h2) => wb.sheetIndex(h2.sid) * 1e12 + (findState.by === "cols" ? h2.c * MAXR + h2.r : h2.r * MAXC + h2.c)
    const curKey = order(cur)
    const next = hits.find((h2) => order(h2) > curKey) || hits[0]
    if (next.sid !== sh.id) activateSheet(next.sid)
    setSel(next.r, next.c)
    status.textContent = `${addr(next.r, next.c)} · ${hits.length} ${t("matches", "نتيجة")}`
    return next
  }
  function replaceIn(text) {
    const re = findMatcher()
    return text.replace(re, findState.re ? findState.rep : () => findState.rep)
  }
  function replaceOne(status) {
    const re = findMatcher()
    if (!re) return
    const text = cellSearchText(sh, sel.r, sel.c)
    re.lastIndex = 0
    if (!text || !re.test(text)) return findNext(status)
    const cell = sh.get(sel.r, sel.c)
    const src = findState.look === "formulas" && cell?.f != null ? "=" + cell.f : editText(sel.r, sel.c)
    const out = replaceIn(src)
    doOps([{ t: "cells", s: sh.id, d: [[sel.r, sel.c, inputPatch(sh, sel.r, sel.c, out)]] }], { label: t("Replace", "استبدال") })
    findNext(status)
  }
  function replaceAll(status) {
    const hits = findAll()
    const bySheet = new Map()
    for (const hit of hits) {
      const sheet = wb.byId.get(hit.sid)
      const cell = sheet.get(hit.r, hit.c)
      if (!cell) continue
      if (sheet.protect && !styleOf(cell.s).ul) continue
      const src = findState.look === "formulas" && cell.f != null ? "=" + cell.f : cell.f != null ? null : editText.call(null, hit.r, hit.c)
      if (src == null) continue
      const out = replaceIn(sheet === sh ? src : plainText(cell.v))
      if (out === src) continue
      if (!bySheet.has(hit.sid)) bySheet.set(hit.sid, [])
      bySheet.get(hit.sid).push([hit.r, hit.c, inputPatch(sheet, hit.r, hit.c, out)])
    }
    const ops = [...bySheet].map(([sid, d]) => ({ t: "cells", s: sid, d }))
    const n = ops.reduce((s, o) => s + o.d.length, 0)
    if (n) doOps(ops, { label: t("Replace all", "استبدال الكل") })
    status.textContent = t(`All done. We made ${n} replacements.`, `تم. أجرينا ${n} عملية استبدال.`)
  }

  /* ---------- Go To ---------- */
  function gotoDialog() {
    const inp = input("", { placeholder: "A1, Sheet2!B5:C20, " + t("or a name", "أو اسم"), autofocus: true })
    const list = h("select.ds-input", { size: 8 })
    for (const n of wb.names.values()) list.append(h("option", { value: n.name }, n.name + "  →  " + n.ref))
    for (const tb of wb.tableMap.values()) list.append(h("option", { value: tb.name }, tb.name + "  (" + t("table", "جدول") + ")"))
    list.addEventListener("change", () => (inp.value = list.value))
    list.addEventListener("dblclick", () => (goToRef(list.value), dialogs[dialogs.length - 1]?.close(true)))
    dialog({
      title: t("Go to", "انتقال إلى"),
      body: h("div", field(t("Reference", "المرجع"), inp), list.options.length ? field(t("Names and tables", "الأسماء والجداول"), list) : null),
      buttons: [{ label: t("Special…", "خاص…"), left: true, action: () => (later(gotoSpecialDialog, 0), true) }, { label: t("Cancel", "إلغاء") }, { label: t("Go", "انتقال"), primary: true, action: () => (goToRef(inp.value) ? true : (toast(t("Reference isn't valid.", "المرجع غير صالح.")), false)) }],
    })
  }
  function gotoSpecialDialog() {
    const opts = [
      ["blanks", t("Blanks", "الفراغات")],
      ["constants", t("Constants", "الثوابت")],
      ["formulas", t("Formulas", "الصيغ")],
      ["errors", t("Formula errors", "أخطاء الصيغ")],
      ["comments", t("Comments", "التعليقات")],
      ["region", t("Current region", "المنطقة الحالية")],
      ["last", t("Last cell", "آخر خلية")],
      ["visible", t("Visible cells only", "الخلايا المرئية فقط")],
      ["cf", t("Conditional formats", "التنسيقات الشرطية")],
      ["validation", t("Data validation", "التحقق من صحة البيانات")],
      ["diffrow", t("Row differences", "اختلافات الصفوف")],
    ]
    const body = h("div.ds-cols2", opts.map(([v, l], i) => radio("special", v, l, i === 0)))
    dialog({ title: t("Go to special", "انتقال إلى خاص"), body, buttons: [{ label: t("Cancel", "إلغاء") }, { label: t("OK", "موافق"), primary: true, action: () => selectSpecial(body.querySelector("input:checked").value) }] })
  }
  function selectSpecial(kind) {
    const scope = sel.ranges.length === 1 && lastRange().r1 === lastRange().r2 && lastRange().c1 === lastRange().c2 ? sh.usedRange(true) || R0() : boundedRect(lastRange())
    const pick = []
    if (kind === "region") {
      const g = currentRegion(sel.r, sel.c)
      if (g) setRange(g, sel)
      return
    }
    if (kind === "last") {
      const u = sh.usedRange(true)
      if (u) setSel(u.r2, u.c2)
      return
    }
    for (let r = scope.r1; r <= Math.min(scope.r2, scope.r1 + 100000); r++) {
      if (kind === "visible" && sh.rows.isHidden(r)) continue
      for (let c = scope.c1; c <= Math.min(scope.c2, scope.c1 + 1000); c++) {
        const cell = sh.get(r, c)
        let ok = false
        switch (kind) {
          case "blanks":
            ok = !sh.hasContent(r, c) && !sh.spillOwner.has(ck(r, c))
            break
          case "constants":
            ok = !!cell && cell.f == null && cell.v != null && cell.v !== ""
            break
          case "formulas":
            ok = !!cell && cell.f != null
            break
          case "errors":
            ok = wb.getValue(sh.id, r, c) instanceof XErr
            break
          case "comments":
            ok = sh.comments.has(ck(r, c))
            break
          case "visible":
            ok = !sh.cols.isHidden(c)
            break
          case "cf":
            ok = sh.cf.some((rule) => inRanges(rule.ranges, r, c))
            break
          case "validation":
            ok = !!dvFor(sh, r, c)
            break
          case "diffrow":
            ok = cmpVals(wb.getValue(sh.id, r, c), wb.getValue(sh.id, r, scope.c1)) !== 0
            break
          default:
        }
        if (ok) pick.push({ r1: r, c1: c, r2: r, c2: c })
      }
    }
    if (!pick.length) return toast(t("No cells were found.", "لم يتم العثور على خلايا."))
    // merge horizontal runs to keep the selection compact
    const merged = []
    for (const g of pick) {
      const last = merged[merged.length - 1]
      if (last && last.r1 === g.r1 && last.r2 === g.r2 && last.c2 === g.c1 - 1) last.c2 = g.c2
      else merged.push({ ...g })
    }
    sel.ranges = merged.slice(0, 5000)
    sel.ri = 0
    sel.r = merged[0].r1
    sel.c = merged[0].c1
    scrollToCell(sel.r, sel.c)
    selChanged()
    toast(t(`${pick.length} cell(s) selected.`, `تم تحديد ${pick.length} خلية.`))
  }

  /* ---------- small dialogs ---------- */
  function zoomDialog() {
    const vals = [200, 150, 125, 100, 75, 50, 25]
    const cur = Math.round(zoomOf() * 100)
    const custom = input(String(cur), { type: "number", min: 25, max: 400 })
    const body = h("div.ds-stack", vals.map((v) => radio("zoom", String(v), v + "%", v === cur)), radio("zoom", "sel", t("Fit selection", "احتواء التحديد"), false), h("label.ds-check", h("input", { type: "radio", name: "zoom", value: "custom", checked: !vals.includes(cur) }), h("span", t("Custom:", "مخصص:")), custom))
    dialog({ title: t("Zoom", "تكبير/تصغير"), body, buttons: [{ label: t("Cancel", "إلغاء") }, { label: t("OK", "موافق"), primary: true, action: () => { const v = body.querySelector("input:checked").value; if (v === "sel") zoomToSelection(); else setZoom((v === "custom" ? +custom.value : +v) / 100) } }] })
  }
  function seriesDialog() {
    const g = lastRange()
    const dir = select([["cols", t("Columns", "أعمدة")], ["rows", t("Rows", "صفوف")]], g.r2 - g.r1 >= g.c2 - g.c1 ? "cols" : "rows")
    const type = select([["linear", t("Linear", "خطي")], ["growth", t("Growth", "نمو")], ["date", t("Date", "تاريخ")], ["auto", t("AutoFill", "تعبئة تلقائية")]], "linear")
    const unit = select([["day", t("Day", "يوم")], ["weekday", t("Weekday", "يوم عمل")], ["month", t("Month", "شهر")], ["year", t("Year", "سنة")]], "day")
    const step = input("1", { type: "number" })
    const stop = input("", { type: "number" })
    dialog({
      title: t("Series", "سلسلة"),
      body: h("div.ds-grid2", field(t("Series in", "السلسلة في"), dir), field(t("Type", "النوع"), type), field(t("Date unit", "وحدة التاريخ"), unit), field(t("Step value", "قيمة الخطوة"), step), field(t("Stop value", "قيمة التوقف"), stop)),
      buttons: [
        { label: t("Cancel", "إلغاء") },
        {
          label: t("OK", "موافق"),
          primary: true,
          action: () => {
            const vertical = dir.value === "cols"
            const st = Number(step.value) || 1
            const lim = stop.value === "" ? null : Number(stop.value)
            const d = []
            const lines = vertical ? g.c2 - g.c1 + 1 : g.r2 - g.r1 + 1
            const len = vertical ? g.r2 - g.r1 + 1 : g.c2 - g.c1 + 1
            if (type.value === "auto") return runFill(vertical ? { ...g, r2: g.r1 } : { ...g, c2: g.c1 }, vertical ? { ...g, r1: g.r1 + 1 } : { ...g, c1: g.c1 + 1 }, "series")
            for (let li = 0; li < lines; li++) {
              const r0 = vertical ? g.r1 : g.r1 + li
              const c0 = vertical ? g.c1 + li : g.c1
              let v = wb.getValue(sh.id, r0, c0)
              if (typeof v !== "number") continue
              for (let k = 1; k < len; k++) {
                if (type.value === "linear") v += st
                else if (type.value === "growth") v *= st
                else {
                  const p = dateParts(v)
                  if (unit.value === "day") v += st
                  else if (unit.value === "weekday") {
                    let n = st
                    while (n > 0) {
                      v++
                      const wd = dateParts(v).wd
                      if (wd !== 0 && wd !== 6) n--
                    }
                  } else if (unit.value === "month") v = serialFromYMD(p.y, p.m + st, Math.min(p.d, daysInMonth(p.y + Math.floor((p.m - 1 + st) / 12), ((p.m - 1 + st) % 12 + 12) % 12 + 1)))
                  else v = serialFromYMD(p.y + st, p.m, p.d)
                }
                if (lim != null && (st > 0 ? v > lim : v < lim)) break
                d.push([vertical ? r0 + k : r0, vertical ? c0 : c0 + k, { v: roundDec(v, 12), f: null }])
              }
            }
            doOps([{ t: "cells", s: sh.id, d }], { label: t("Series", "سلسلة") })
          },
        },
      ],
    })
  }
  function linkDialog() {
    const cell = sh.get(sel.r, sel.c)
    const text = input(cell && cell.f == null ? plainText(cell.v) : "", { placeholder: t("Text to display", "النص المعروض") })
    const url = input(cell?.l || "", { placeholder: "https://… " + t("or #Sheet2!A1", "أو #Sheet2!A1"), autofocus: true })
    const place = select([["", t("Web address or e-mail", "عنوان ويب أو بريد")], ...wb.sheets.map((s) => ["#" + quoteSheet(s.name) + "!A1", t("Place in this workbook: ", "مكان في هذا المصنف: ") + s.name]), ...[...wb.names.values()].map((n) => ["#" + n.name, t("Name: ", "اسم: ") + n.name])], "")
    place.addEventListener("change", () => place.value && (url.value = place.value))
    dialog({
      title: t("Insert link", "إدراج ارتباط"),
      body: h("div", field(t("Text to display", "النص المعروض"), text), field(t("Address", "العنوان"), url), field(t("Link to", "ارتباط بـ"), place)),
      buttons: [
        cell?.l ? { label: t("Remove link", "إزالة الارتباط"), left: true, action: () => doOps([{ t: "cells", s: sh.id, d: [[sel.r, sel.c, { l: null }]] }]) } : null,
        { label: t("Cancel", "إلغاء") },
        {
          label: t("OK", "موافق"),
          primary: true,
          action: () => {
            let u = url.value.trim()
            if (!u) return false
            if (/^[\w.+-]+@[\w-]+\.[\w.]+$/.test(u)) u = "mailto:" + u
            const patch = { l: u }
            if (text.value !== (cell && cell.f == null ? plainText(cell.v) : "")) Object.assign(patch, inputPatch(sh, sel.r, sel.c, text.value || u))
            else if (!sh.hasContent(sel.r, sel.c)) Object.assign(patch, { v: u, f: null })
            doOps([{ t: "cells", s: sh.id, d: [[sel.r, sel.c, patch]] }], { label: t("Link", "ارتباط") })
          },
        },
      ].filter(Boolean),
    })
  }
  function insertFunctionCall(name) {
    if (!edit.active) startEdit({ mode: "enter", text: "=" })
    const el = inputEl()
    const a = el.selectionStart
    const before = el.value.slice(0, a)
    const ins = (/[=(,+\-*/^&<>:;\s]$/.test(before) ? "" : "+") + name + "("
    el.value = before + ins + el.value.slice(el.selectionEnd)
    el.setSelectionRange(a + ins.length, a + ins.length)
    el.focus()
    syncHighlight()
  }
  function insertFunctionDialog() {
    const search = input("", { placeholder: t("Search for a function", "ابحث عن دالة"), autofocus: true })
    const cat = select([["all", t("All", "الكل")], ...Object.keys(FN_CATS).map((k) => [k, AR ? FN_CATS_AR[k] : FN_CATS[k]])], "all")
    const list = h("select.ds-input", { size: 12 })
    const info = h("div.ds-fninfo")
    const fill = () => {
      const q = search.value.trim().toUpperCase()
      list.innerHTML = ""
      const names = [...FN_HELP.keys()].filter((n) => (cat.value === "all" || FN_HELP.get(n).cat === cat.value) && (!q || n.includes(q) || FN_HELP.get(n).desc.toUpperCase().includes(q)))
      for (const n of names) list.append(h("option", { value: n }, n))
      if (list.options.length) list.selectedIndex = 0
      show()
    }
    const show = () => {
      const f = FN_HELP.get(list.value)
      info.innerHTML = f ? `<b>${esc(f.name)}(${esc(f.args)})</b><p>${esc(f.desc)}</p>` : ""
    }
    search.addEventListener("input", fill)
    cat.addEventListener("change", fill)
    list.addEventListener("change", show)
    fill()
    const d = dialog({ title: t("Insert function", "إدراج دالة"), body: h("div", h("div.ds-grid2", field(t("Search", "بحث"), search), field(t("Category", "الفئة"), cat)), list, info), buttons: [{ label: t("Cancel", "إلغاء") }, { label: t("OK", "موافق"), primary: true, action: () => list.value && insertFunctionCall(list.value) }] })
    list.addEventListener("dblclick", () => {
      d.close(true)
      insertFunctionCall(list.value)
    })
  }

  /* ---------- names ---------- */
  function namesList() {
    return [...wb.names.values()]
  }
  function setNames(list, label) {
    doOps([{ t: "wbmeta", k: "names", v: list.map(({ name, ref, scope, comment }) => ({ name, ref, scope, comment })) }], { label })
  }
  function validName(name) {
    return /^[A-Za-z_\\¡-￿][\w.¡-￿]*$/.test(name) && !looksLikeCell(name) && !/^R\d*C\d*$/i.test(name) && !/^(TRUE|FALSE)$/i.test(name)
  }
  async function defineNameDialog(existing) {
    const g = lastRange()
    const name = input(existing?.name || (sh.get(g.r1 - 1 >= 0 ? g.r1 - 1 : g.r1, g.c1)?.v && typeof sh.get(Math.max(0, g.r1 - 1), g.c1)?.v === "string" ? String(sh.get(Math.max(0, g.r1 - 1), g.c1).v).replace(/\W+/g, "_") : ""), { autofocus: true })
    const scope = select([["", t("Workbook", "المصنف")], ...wb.sheets.map((s) => [String(s.id), s.name])], existing?.scope != null ? String(existing.scope) : "")
    const comment = input(existing?.comment || "")
    const ref = input(existing ? "=" + String(existing.ref).replace(/^=/, "") : "=" + quoteSheet(sh.name) + "!" + rangeText(g).replace(/([A-Z]+)(\d+)/g, "$$$1$$$2"), { spellcheck: "false" })
    const r = await dialog({
      title: existing ? t("Edit name", "تحرير الاسم") : t("New name", "اسم جديد"),
      body: h("div", field(t("Name", "الاسم"), name), field(t("Scope", "النطاق"), scope), field(t("Comment", "تعليق"), comment), field(t("Refers to (a range, a value or a formula such as =LAMBDA(x, x*2))", "يشير إلى (نطاق أو قيمة أو صيغة مثل =LAMBDA(x, x*2))"), ref)),
      buttons: [
        { label: t("Cancel", "إلغاء") },
        {
          label: t("OK", "موافق"),
          primary: true,
          action: () => {
            const nm = name.value.trim()
            if (!validName(nm)) return alertBox(t("The name you entered is not valid. Names start with a letter or underscore, contain no spaces, and can't look like a cell reference.", "الاسم الذي أدخلته غير صالح. يجب أن تبدأ الأسماء بحرف أو شرطة سفلية ولا تحتوي على مسافات ولا تشبه مرجع خلية.")).then(() => false)
            const formula = ref.value.trim().replace(/^=?/, "")
            try {
              parseFormula(formula)
            } catch (e) {
              return alertBox(t("There's a problem with this formula: ", "هناك مشكلة في هذه الصيغة: ") + e.message).then(() => false)
            }
            const sc = scope.value === "" ? null : Number(scope.value)
            const list = namesList().filter((n) => !(existing && n.name === existing.name && (n.scope ?? null) === (existing.scope ?? null)))
            if (list.some((n) => n.name.toUpperCase() === nm.toUpperCase() && (n.scope ?? null) === sc)) return alertBox(t("That name already exists. Names must be unique.", "هذا الاسم موجود. يجب أن تكون الأسماء فريدة.")).then(() => false)
            list.push({ name: nm, ref: "=" + formula, scope: sc, comment: comment.value })
            setNames(list, t("Define name", "تعريف اسم"))
          },
        },
      ],
    }).done
    return r
  }
  function nameManager() {
    const table = h("table.ds-table.ds-names")
    const draw = () => {
      table.innerHTML = `<tr><th>${t("Name", "الاسم")}</th><th>${t("Value", "القيمة")}</th><th>${t("Refers to", "يشير إلى")}</th><th>${t("Scope", "النطاق")}</th><th></th></tr>`
      for (const n of namesList()) {
        let val = ""
        try {
          const ast = parseFormula(String(n.ref).replace(/^=/, ""))
          const v = evalAst(ast, wb, n.scope ?? sh.id, 0, 0)
          val = v instanceof Ref ? (v.single ? displayOf(wb.byId.get(v.sid), v.r1, v.c1) : `{${rectAddr(v.r1, v.c1, v.r2, v.c2)}}`) : v instanceof Lambda ? "LAMBDA" : v instanceof Mat ? "{…}" : plainText(v)
        } catch {
          val = "#NAME?"
        }
        const tr = h("tr", h("td", n.name), h("td", val), h("td.mono", n.ref), h("td", n.scope != null ? wb.sheetName(n.scope) : t("Workbook", "المصنف")))
        const actions = h("td.ds-actions")
        const edt = h("button.ds-icon", { type: "button", title: t("Edit", "تحرير"), html: icon("edit") })
        edt.addEventListener("click", async () => {
          await defineNameDialog(n)
          draw()
        })
        const del = h("button.ds-icon", { type: "button", title: t("Delete", "حذف"), html: icon("trash") })
        del.addEventListener("click", () => {
          setNames(namesList().filter((x) => x !== n), t("Delete name", "حذف اسم"))
          draw()
        })
        actions.append(edt, del)
        tr.append(actions)
        table.append(tr)
      }
      if (!wb.names.size) table.append(h("tr", h("td", { colspan: 5 }, t("No names yet. Names make formulas easier to read, and a name that holds a LAMBDA becomes your own function.", "لا توجد أسماء بعد. تجعل الأسماء الصيغ أسهل في القراءة، والاسم الذي يحتوي على LAMBDA يصبح دالتك الخاصة."))))
    }
    draw()
    dialog({ title: t("Name manager", "إدارة الأسماء"), body: table, wide: true, buttons: [{ label: t("New…", "جديد…"), left: true, action: async () => (await defineNameDialog(), draw(), false) }, { label: t("Close", "إغلاق"), primary: true }] })
  }
  async function namesFromSelection() {
    const g = boundedRect(lastRange())
    const body = h("div.ds-stack", check(t("Top row", "الصف العلوي"), true, { name: "top" }), check(t("Left column", "العمود الأيسر"), false, { name: "left" }), check(t("Bottom row", "الصف السفلي"), false, { name: "bottom" }), check(t("Right column", "العمود الأيمن"), false, { name: "right" }))
    const ok = await dialog({ title: t("Create names from selection", "إنشاء أسماء من التحديد"), body, buttons: [{ label: t("Cancel", "إلغاء"), value: false }, { label: t("OK", "موافق"), primary: true, value: true }] }).done
    if (ok !== true) return
    const on = (n) => body.querySelector(`[name="${n}"]`).checked
    const list = namesList()
    const add = (label, r1, c1, r2, c2) => {
      let nm = String(label ?? "").trim().replace(/[^\w.¡-￿]+/g, "_")
      if (!nm) return
      if (!/^[A-Za-z_¡-￿]/.test(nm) || looksLikeCell(nm)) nm = "_" + nm
      if (list.some((n) => n.name.toUpperCase() === nm.toUpperCase() && n.scope == null)) return
      list.push({ name: nm, ref: "=" + quoteSheet(sh.name) + "!" + rectAddr(r1, c1, r2, c2).replace(/([A-Z]+)(\d+)/g, "$$$1$$$2"), scope: null })
    }
    const r1 = g.r1 + (on("top") ? 1 : 0)
    const r2 = g.r2 - (on("bottom") ? 1 : 0)
    const c1 = g.c1 + (on("left") ? 1 : 0)
    const c2 = g.c2 - (on("right") ? 1 : 0)
    if (on("top")) for (let c = c1; c <= c2; c++) add(wb.getValue(sh.id, g.r1, c), r1, c, r2, c)
    if (on("bottom")) for (let c = c1; c <= c2; c++) add(wb.getValue(sh.id, g.r2, c), r1, c, r2, c)
    if (on("left")) for (let r = r1; r <= r2; r++) add(wb.getValue(sh.id, r, g.c1), r, c1, r, c2)
    if (on("right")) for (let r = r1; r <= r2; r++) add(wb.getValue(sh.id, r, g.c2), r, c1, r, c2)
    setNames(list, t("Create names", "إنشاء أسماء"))
  }

