      if (cur.length) segs.push(cur)
      for (const seg of segs) {
        if (st === "area") {
          const base = stacked && i > 0 ? null : zero
          const back = base != null ? `L${seg[seg.length - 1][0]},${base}L${seg[0][0]},${base}Z` : "Z"
          out += `<path d="M${seg.map((p) => p[0] + "," + p[1]).join("L")}${back}" fill="${col}" fill-opacity="${stacked ? 0.85 : 0.35}" stroke="${col}" stroke-width="1.5"/>`
        } else if (st === "line") out += `<polyline points="${seg.map((p) => p[0] + "," + p[1]).join(" ")}" fill="none" stroke="${col}" stroke-width="2.2" stroke-linejoin="round" stroke-linecap="round"/>`
      }
