      const sheetName = refs[0].sheet || sheet.name
      const box = refs.reduce((a, b) => ({ r1: Math.min(a.r1, b.r1), c1: Math.min(a.c1, b.c1), r2: Math.max(a.r2, b.r2), c2: Math.max(a.c2, b.c2) }))
      const titleText = all(all(cx, "title")[0], "t").map((x) => x.textContent).join("") || null
