      buttons: [{ label: t("Close", "إغلاق") }, { label: opts.pdf ? t("Save as PDF", "حفظ كملف PDF") : t("Print", "طباعة"), primary: true, action: () => (opts.pdf ? exportPdf(what.value) : doPrint(what.value)) }],
