            s.rows("B8", [[t("Description", "الوصف"), t("Qty", "الكمية"), t("Unit price", "سعر الوحدة"), t("Amount", "المبلغ")]], HEAD(ac[0]))
            const items = [[t("Consulting services", "خدمات استشارية"), 10, 450], [t("Software license", "ترخيص برنامج"), 2, 1200], [t("Support (monthly)", "دعم (شهري)"), 1, 800]]
            s.rows("B9", items)
            for (let r = 9; r <= 16; r++) s.set("E" + r, `=IF(C${r}="","",C${r}*D${r})`)
